def choose_move(observation):
    w = observation['grid_width']
    h = observation['grid_height']
    px, py = observation['self_position']
    ops = observation.get('opponent_position', [])
    res = observation.get('resources', [])
    obstacles = set(tuple(obs) for obs in observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    if res:
        target = min(res, key=lambda r: dist((px, py), (r[0], r[1])))
    elif ops:
        target = min(ops, key=lambda o: dist((px, py), (o[0], o[1])))
    dx, dy = 0, 0
    if target:
        diff_x, diff_y = target[0] - px, target[1] - py
        if abs(diff_x) > abs(diff_y):
            dx = 1 if diff_x > 0 else -1 if diff_x < 0 else 0
        elif abs(diff_y) > 0:
            dy = 1 if diff_y > 0 else -1
    new_pos = (px + dx, py + dy)
    if (0 <= new_pos[0] < w and 0 <= new_pos[1] < h and new_pos not in obstacles):
        return [dx, dy]
    else:
        for ndx, ndy in [(1,0), (-1,0), (0,1), (0,-1)]:
            nx, ny = px + ndx, py + ndy
            if (0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles):
                return [ndx, ndy]
    return [0,0]
